program.source:
Function total <- SumaHasta(n As Integer)
  Define total As Integer;
  total <- n + SumaHasta(n - 1);
EndFunction

Algorithm Principal
  Define n As Integer;
  Read n;
  Write SumaHasta(n);
EndAlgorithm

